-- 514b — Demandes initiales de photos pour les guides d'arrivée (20/10/2026, accord d'Oïhan).
-- Source : photos manquantes des brouillons, vérifiées le 20/10 contre les « à compléter » actuels (toutes encore manquantes).
-- Exclus : SUZETTE (accueil en personne et hors location : coffre à clés sans objet), ZURBIAC (pause), MARNEKO et ARREBA (archivés).
-- Maison Maïté (M-MAITE + PANTXIKA, IBANETA, GAXUXA, TXOMIN, BIXINTXO) : une seule demande, la façade sert aux 6 guides.
-- Rattachement aux missions : arrivee_photo_planifier() (514).
with src as (select * from jsonb_to_recordset('[{"code": "506P", "codes": ["506P"], "photos": [{"cle": "p1", "libelle": "Hall de la résidence et accès aux ascenseurs depuis l''entrée", "cibles": [{"bien_code": "506P", "etape_id": "etage"}]}]}, {"code": "AITZINA", "codes": ["AITZINA"], "photos": [{"cle": "p1", "libelle": "Portail d''entrée de la propriété", "cibles": [{"bien_code": "AITZINA", "etape_id": "portail"}]}]}, {"code": "B24", "codes": ["B24"], "photos": [{"cle": "p1", "libelle": "Coffre à clés au niveau de la place 24 (fermé, code illisible)", "cibles": [{"bien_code": "B24", "etape_id": "cles"}]}, {"cle": "p2", "libelle": "Porte de l''appartement n°24 (2e étage à gauche)", "cibles": [{"bien_code": "B24", "etape_id": "appartement"}]}]}, {"code": "BGH", "codes": ["BGH"], "photos": [{"cle": "p1", "libelle": "Portillon après la porte verte", "cibles": [{"bien_code": "BGH", "etape_id": "portillon"}]}]}, {"code": "DUL", "codes": ["DUL"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement (2e étage, porte de gauche)", "cibles": [{"bien_code": "DUL", "etape_id": "etage"}]}]}, {"code": "LAGREOU", "codes": ["LAGREOU"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement (1er étage à gauche) avec le coffre à clés fermé", "cibles": [{"bien_code": "LAGREOU", "etape_id": "cles"}]}]}, {"code": "M-MAITE", "codes": ["M-MAITE", "PANTXIKA", "IBANETA", "GAXUXA", "TXOMIN", "BIXINTXO"], "photos": [{"cle": "p1", "libelle": "Façade et porte d''entrée de la Maison Maïté, 5 rue d''Alger", "cibles": [{"bien_code": "PANTXIKA", "etape_id": "pieton-acces"}, {"bien_code": "IBANETA", "etape_id": "adresse-acces"}, {"bien_code": "GAXUXA", "etape_id": "accueil-cles"}, {"bien_code": "TXOMIN", "etape_id": "arrivee-reussie"}, {"bien_code": "BIXINTXO", "etape_id": "arrivee-maison"}, {"bien_code": "M-MAITE", "etape_id": "remise-cles"}]}]}, {"code": "VIKY", "codes": ["VIKY"], "photos": [{"cle": "p1", "libelle": "Boîte aux lettres n°55 avec le coffre à clés (fermé, code illisible)", "cibles": [{"bien_code": "VIKY", "etape_id": "cles"}]}, {"cle": "p2", "libelle": "Entrée du garage (2e porte à droite) et place n°5", "cibles": [{"bien_code": "VIKY", "etape_id": "parking"}]}, {"cle": "p3", "libelle": "2e porte vitrée près de l''ascenseur", "cibles": [{"bien_code": "VIKY", "etape_id": "pieton_porte"}]}, {"cle": "p4", "libelle": "Porte n°55 (1er étage à gauche)", "cibles": [{"bien_code": "VIKY", "etape_id": "porte"}]}]}, {"code": "ITS", "codes": ["ITS"], "photos": [{"cle": "p1", "libelle": "Porte piétonne du parking", "cibles": [{"bien_code": "ITS", "etape_id": "parking-sortie"}]}, {"cle": "p2", "libelle": "Porte de l''appartement (dernier étage, porte de gauche)", "cibles": [{"bien_code": "ITS", "etape_id": "etage"}]}]}, {"code": "B16", "codes": ["B16"], "photos": [{"cle": "p1", "libelle": "Coffre à clés au niveau de la place 16 (fermé, code illisible)", "cibles": [{"bien_code": "B16", "etape_id": "cles"}]}, {"cle": "p2", "libelle": "Couloir du 1er étage et porte n°16 au fond", "cibles": [{"bien_code": "B16", "etape_id": "porte"}]}]}, {"code": "BORDEZIA", "codes": ["BORDEZIA"], "photos": [{"cle": "p1", "libelle": "Entrée de l''immeuble, 29 rue des Retaillons", "cibles": [{"bien_code": "BORDEZIA", "etape_id": "immeuble"}]}]}, {"code": "MUNDUZ", "codes": ["MUNDUZ"], "photos": [{"cle": "p1", "libelle": "Portillon piéton depuis la place de parking", "cibles": [{"bien_code": "MUNDUZ", "etape_id": "portillon"}]}]}, {"code": "EGOA", "codes": ["EGOA"], "photos": [{"cle": "p1", "libelle": "Portillon avec la boîte à clés accrochée (fermée, code illisible)", "cibles": [{"bien_code": "EGOA", "etape_id": "cle-boite"}]}, {"cle": "p2", "libelle": "Porte du logement", "cibles": [{"bien_code": "EGOA", "etape_id": "arrivee-logement"}]}]}, {"code": "BITXI", "codes": ["BITXI"], "photos": [{"cle": "p1", "libelle": "Cour et escalier de droite, au fond", "cibles": [{"bien_code": "BITXI", "etape_id": "cour-escalier"}]}, {"cle": "p2", "libelle": "Porte de l''appartement en haut de l''escalier de droite", "cibles": [{"bien_code": "BITXI", "etape_id": "appartement"}]}]}, {"code": "APPARTEMENT", "codes": ["APPARTEMENT"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement (1er étage, porte de gauche)", "cibles": [{"bien_code": "APPARTEMENT", "etape_id": "etage"}]}]}, {"code": "XABADENIA", "codes": ["XABADENIA"], "photos": [{"cle": "p1", "libelle": "Seconde porte vitrée de la résidence", "cibles": [{"bien_code": "XABADENIA", "etape_id": "seconde_porte"}]}]}, {"code": "PATXI", "codes": ["PATXI"], "photos": [{"cle": "p1", "libelle": "Coffre à clés dans la 1re boîte aux lettres à gauche (fermé, code illisible)", "cibles": [{"bien_code": "PATXI", "etape_id": "cles"}]}]}, {"code": "408P", "codes": ["408P"], "photos": [{"cle": "p1", "libelle": "Hall Palais et accès aux ascenseurs depuis l''entrée du n°23", "cibles": [{"bien_code": "408P", "etape_id": "hall"}]}]}, {"code": "CERES", "codes": ["CERES"], "photos": [{"cle": "p1", "libelle": "Façade et entrée de l''immeuble, 5 rue de l''Abbé Pierre Moussempès", "cibles": [{"bien_code": "CERES", "etape_id": "immeuble-digicode"}]}]}, {"code": "AITA", "codes": ["AITA"], "photos": [{"cle": "p1", "libelle": "Chemin vers l''appartement, à droite de la maison", "cibles": [{"bien_code": "AITA", "etape_id": "vers-appartement"}]}]}, {"code": "COTREL", "codes": ["COTREL"], "photos": [{"cle": "p1", "libelle": "Façade et porte d''entrée côté rue, 34 rue Cotrel", "cibles": [{"bien_code": "COTREL", "etape_id": "adresse-logement"}]}]}, {"code": "AUREAN", "codes": ["AUREAN"], "photos": [{"cle": "p1", "libelle": "Boîte aux lettres n°63 avec le coffre à clés (fermé, code illisible)", "cibles": [{"bien_code": "AUREAN", "etape_id": "cles"}]}, {"cle": "p2", "libelle": "Ascenseur et porte de l''appartement (6e étage, à gauche)", "cibles": [{"bien_code": "AUREAN", "etape_id": "porte"}]}]}, {"code": "PANORAMA", "codes": ["PANORAMA"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement (6e étage, après les 5 marches à droite)", "cibles": [{"bien_code": "PANORAMA", "etape_id": "porte"}]}]}, {"code": "ENEKO", "codes": ["ENEKO"], "photos": [{"cle": "p1", "libelle": "Porte du studio, à droite de la maison", "cibles": [{"bien_code": "ENEKO", "etape_id": "porte"}]}]}, {"code": "MIRAMARVEL", "codes": ["MIRAMARVEL"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement 85 (4e étage, à gauche après l''ascenseur)", "cibles": [{"bien_code": "MIRAMARVEL", "etape_id": "porte"}]}]}, {"code": "EKIA", "codes": ["EKIA"], "photos": [{"cle": "p1", "libelle": "Portail vert côté route (avant le petit portail en bois)", "cibles": [{"bien_code": "EKIA", "etape_id": "portails"}]}]}, {"code": "ALAIA", "codes": ["ALAIA"], "photos": [{"cle": "p1", "libelle": "Porte de l''appartement 23 (2e étage, au bout à gauche)", "cibles": [{"bien_code": "ALAIA", "etape_id": "porte"}]}]}]'::jsonb) as s(code text, codes text[], photos jsonb)),
r as (
  select s.code,
         array(select b.id from public.bien b where b.code = any(s.codes)) as bien_ids,
         (select jsonb_agg(jsonb_set(p, '{cibles}', (select jsonb_agg(c || jsonb_build_object('bien_id', (select b.id from public.bien b where b.code = c->>'bien_code'))) from jsonb_array_elements(p->'cibles') c)) order by o)
            from jsonb_array_elements(s.photos) with ordinality as e(p, o)) as photos
  from src s)
insert into public.arrivee_photo_demande (bien_id, bien_ids, photos, cree_par_nom, note)
select b.id, r.bien_ids, r.photos, 'Oïhan (accord 20/10/2026)',
       case when r.code = 'M-MAITE' then 'Maison Maïté + 5 chambres : une photo de façade pour les 6 guides' else 'Photos manquantes du guide d''arrivée' end
from r join public.bien b on b.code = r.code
where not exists (select 1 from public.arrivee_photo_demande x where x.bien_id = b.id and x.statut in ('a_planifier', 'planifiee'));
